"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["35369"],{43788(e){e.exports=JSON.parse('{"id":"V4-137","slug":"offset-mortgage","term":"Offset Mortgage","also_known_as":[],"difficulty":"Intermediate","definition":"An offset mortgage is a mortgage linked to the borrower\u2019s savings or current account, so that the savings balance is deducted from the mortgage balance when interest is calculated.","explanation":["With an offset mortgage, savings do not earn interest. Instead, they reduce the amount of the mortgage on which interest is charged.","For example, a borrower has a mortgage of 200,000 and savings of 30,000 in a linked account. They pay interest on only 170,000. The borrower can either keep paying the same monthly amount, so the mortgage is repaid faster, or pay a lower monthly amount.","Offset mortgages can be especially attractive for higher-rate taxpayers, because the saving on mortgage interest is not taxed, whereas interest earned on savings may be. They also suit people with large savings who want to keep them accessible, such as self-employed people setting aside money for tax bills.","Offset mortgages are available in the United Kingdom and Australia, where similar arrangements are often called offset accounts. They often carry slightly higher interest rates than standard mortgages, so they are most worthwhile when the borrower keeps a substantial savings balance. Borrowers can usually withdraw their savings at any time, although this increases the interest charged."],"note":"","total":1725,"prev":{"slug":"off-balance-sheet-financing","term":"Off-Balance-Sheet Financing"},"next":{"slug":"okun-s-law","term":"Okun\u2019s Law"}}')}}]);